import assert from "node:assert/strict";
import { describe, it } from "node:test";
import connect from "connect";
import supertest from "supertest";
import type { IncomingMessage, ServerResponse } from "node:http";
import contentSecurityPolicy, {
  createNonce,
  getNonce,
} from "../middlewares/content-security-policy/index.js";

describe("Content-Security-Policy createNonce helper", () => {
  it("returns a properly quoted nonce directive value", async () => {
    const nonceFn = createNonce();
    assert.equal(typeof nonceFn, "function", "createNonce should return a function");

    // Create a minimal mock for req/res
    const req = {} as IncomingMessage;
    const res = {
      setHeader: () => {},
    } as unknown as ServerResponse;

    const result = nonceFn(req, res);
    assert.match(
      result,
      /^'nonce-[A-Za-z0-9+/=]+'$/,
      "should return a quoted nonce value",
    );
    assert.ok(
      result.startsWith("'nonce-") && result.endsWith("'"),
      "should start with 'nonce- and end with '",
    );
  });

  it("generates a different nonce for different response objects", async () => {
    const nonceFn = createNonce();
    const req = {} as IncomingMessage;
    const res1 = {
      setHeader: () => {},
    } as unknown as ServerResponse;
    const res2 = {
      setHeader: () => {},
    } as unknown as ServerResponse;

    const result1 = nonceFn(req, res1);
    const result2 = nonceFn(req, res2);

    assert.notEqual(
      result1,
      result2,
      "different response objects should get different nonces",
    );
  });

  it("returns the same nonce for the same response object on subsequent calls", async () => {
    const nonceFn = createNonce();
    const req = {} as IncomingMessage;
    const res = {
      setHeader: () => {},
    } as unknown as ServerResponse;

    const result1 = nonceFn(req, res);
    const result2 = nonceFn(req, res);

    assert.equal(
      result1,
      result2,
      "same response object should get the same nonce",
    );
  });

  it("getNonce retrieves the nonce for a response object", async () => {
    const nonceFn = createNonce();
    const req = {} as IncomingMessage;
    const res = {
      setHeader: () => {},
    } as unknown as ServerResponse;

    const directiveValue = nonceFn(req, res);
    const storedNonce = getNonce(res);

    assert.ok(
      typeof storedNonce === "string",
      "getNonce should return a string",
    );
    assert.ok(
      storedNonce!.length > 0,
      "nonce should not be empty",
    );
    assert.equal(
      directiveValue,
      `'nonce-${storedNonce}'`,
      "directive value should match the stored nonce",
    );
  });

  it("getNonce returns undefined for a response that has no nonce", () => {
    const res = {
      setHeader: () => {},
    } as unknown as ServerResponse;

    assert.equal(
      getNonce(res),
      undefined,
      "getNonce should return undefined for response without nonce",
    );
  });

  it("integrates with the full CSP middleware via a real HTTP request", async () => {
    const nonceFn = createNonce();

    const app = connect()
      .use(
        contentSecurityPolicy({
          useDefaults: false,
          directives: {
            "default-src": ["'self'"],
            "script-src": ["'self'", nonceFn],
          },
        }),
      )
      .use((_req: IncomingMessage, res: ServerResponse) => {
        res.end("Hello world!");
      });

    const response = await supertest(app)
      .get("/")
      .expect(200, "Hello world!");

    const cspHeader = response.header["content-security-policy"];
    assert.ok(typeof cspHeader === "string", "CSP header should be set");

    // Should contain the nonce in script-src
    assert.match(
      cspHeader,
      /script-src 'self' 'nonce-[A-Za-z0-9+/=]+'/,
      "should include script-src with self and a nonce",
    );
  });

  it("returns a base64-encoded nonce of correct byte length (16 bytes)", async () => {
    const nonceFn = createNonce();
    const req = {} as IncomingMessage;
    const res = {
      setHeader: () => {},
    } as unknown as ServerResponse;

    // Call nonceFn to generate and store the nonce
    nonceFn(req, res);
    const nonce = getNonce(res);
    assert.ok(nonce, "nonce should be defined");

    // base64 encoding of 16 bytes is 24 characters (no padding for 16 bytes = 128 bits)
    // 16 bytes * 4/3 = 21.33 → 22 chars with padding = 24 chars with "==" or 22 chars without
    // Actually, 16 bytes = 128 bits. Base64 encodes 3 bytes → 4 chars. 16 bytes = 5 groups of 3 + 1 extra = 5*4 + 2 + 2 padding = 24 chars.
    // But randomBytes(16).toString('base64') returns 24 chars (with "==" at end) or could be 22 chars without padding
    // Let's just check it's reasonable
    assert.ok(nonce.length >= 22 && nonce.length <= 24, "nonce should be ~24 base64 chars for 16 bytes");
  });
});

