    // Generate and store the nonce
    nonceFn(req, res);

    // Retrieve it multiple times
    const first = getNonce(res);
    const second = getNonce(res);
    const third = getNonce(res);

    // All retrievals should return the same nonce
    assert.ok(typeof first === "string", "first call should return a string");
    assert.ok(typeof second === "string", "second call should return a string");
    assert.ok(typeof third === "string", "third call should return a string");
    assert.equal(first, second, "first and second calls should return the same nonce");
    assert.equal(second, third, "second and third calls should return the same nonce");
  });

  it("getNonce should not consume the nonce — the nonce function should still work after getNonce", () => {
    const nonceFn = createNonce();
    const req = {} as IncomingMessage;
    const res = {
      setHeader: () => {},
    } as unknown as ServerResponse;

    // Generate and store the nonce
    const directiveValue = nonceFn(req, res);

