import type { IncomingMessage, ServerResponse } from "node:http";
import crypto from "node:crypto";

type ContentSecurityPolicyDirectiveValueFunction = (
  req: IncomingMessage,
  res: ServerResponse,
) => string;

type ContentSecurityPolicyDirectiveValue =
  | string
  | ContentSecurityPolicyDirectiveValueFunction;

export interface ContentSecurityPolicyOptions {
  useDefaults?: boolean;
  directives?: Record<
    string,
    | null
    | Iterable<ContentSecurityPolicyDirectiveValue>
    | typeof dangerouslyDisableDefaultSrc
  >;
  reportOnly?: boolean;
}

type NormalizedDirectives = Map<
  string,
  Iterable<ContentSecurityPolicyDirectiveValue>
>;

interface ContentSecurityPolicy {
  (
    options?: Readonly<ContentSecurityPolicyOptions>,
  ): (
    req: IncomingMessage,
    res: ServerResponse,
    next: (err?: Error) => void,
  ) => void;
  getDefaultDirectives: typeof getDefaultDirectives;
  createNonce: typeof createNonce;
  getNonce: typeof getNonce;
  dangerouslyDisableDefaultSrc: typeof dangerouslyDisableDefaultSrc;
}

const dangerouslyDisableDefaultSrc = Symbol("dangerouslyDisableDefaultSrc");

const nonceStore = new WeakMap<ServerResponse, string>();

function createNonce(): ContentSecurityPolicyDirectiveValueFunction {
  return function nonceDirectiveValue(
    _req: IncomingMessage,
    res: ServerResponse,
  ): string {
    const existingNonce = nonceStore.get(res);
    if (existingNonce) {
      return `'nonce-${existingNonce}'`;
    }
    const nonce = crypto.randomBytes(16).toString("base64");
    nonceStore.set(res, nonce);
    return `'nonce-${nonce}'`;
  };
}

function getNonce(res: ServerResponse): string | undefined {
  return nonceStore.get(res);
}

const SHOULD_BE_QUOTED: ReadonlySet<string> = new Set([
  "none",
  "self",
  "strict-dynamic",
  "report-sample",
  "inline-speculation-rules",
  "unsafe-inline",
  "unsafe-eval",
  "unsafe-hashes",
  "wasm-unsafe-eval",
]);

const getDefaultDirectives = (): Record<
  string,
  Iterable<ContentSecurityPolicyDirectiveValue>
> => ({
  "default-src": ["'self'"],
  "base-uri": ["'self'"],
  "font-src": ["'self'", "https:", "data:"],
  "form-action": ["'self'"],
  "frame-ancestors": ["'self'"],
  "img-src": ["'self'", "data:"],
  "object-src": ["'none'"],
  "script-src": ["'self'"],
  "script-src-attr": ["'none'"],
  "style-src": ["'self'", "https:", "'unsafe-inline'"],
  "upgrade-insecure-requests": [],
});

const dashify = (str: string): string =>
  str.replace(/[A-Z]/g, (capitalLetter) => "-" + capitalLetter.toLowerCase());

const assertDirectiveValueIsValid = (
  directiveName: string,
  directiveValue: string,
): void => {
  if (/;|,/.test(directiveValue)) {
    throw new Error(
      `Content-Security-Policy received an invalid directive value for ${JSON.stringify(
        directiveName,
      )}`,
    );
